1	package registry
2	
3	import (
4		"errors"
5		"os"
6		"testing"
7		"time"
8	)
9	
10	// 本文件为限时一次性代转（ProxyTransfer）补充"拒绝结果保存失败"场景的
11	// 回归保障，与发行、转让、授权创建/撤销的同类用例行为对齐：授权已到期、
12	// 已撤销、已使用、操作者无权、任一相关账户停用或持有版本已变化等状态类
13	// 业务拒绝，原本要作为该请求的首次结果落盘。若拒绝结果尚未写入原登记册
14	// 就发生写入失败，ProxyTransfer 必须返回实际保存错误，不能只返回原业务
15	// 拒绝，让调用者误以为这次拒绝已经记住。
16	//
17	// 保存失败时返回的结果必须为空：不带授权或藏品编号，不带转让与金额信息，
18	// Replayed 为 false，结果内的 Err 为空，单独返回的 error 保留保存失败的
19	// 原因。授权内容、使用标记、授权变更记录，以及藏品持有人、版本、转让历史
20	// 与版税应付都保持调用前状态；该操作者的本次请求号没有被占用——即使写入
21	// 失败后原登记册数据暂时无法读取，也不能让尚未保存的拒绝留在当前已打开的
22	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用完全相同的
23	// 请求重提，按重提时的业务状态重新判断（例如到期拒绝保存失败、授权随后被
24	// 撤销时，重提返回已撤销），首次重新处理不标回放，保存成功后再次原样重提
25	// 才回放。已经成功保存的拒绝仍按首次结果回放，改动该请求的业务内容仍报
26	// 请求号冲突；必填内容缺失或引用不存在沿用原错误且不占用请求号。
27	//
28	// 失败注入方式与其他场景共用：在临时文件路径 .registry.json.tmp 上预先
29	// 建一个目录，save 在 OpenFile 阶段即以 EISDIR 失败，原快照完好可读；
30	// 另有用例同时破坏数据文件，覆盖"原数据暂时无法读取"的情形。
31	
32	// assertProxySaveFailureEmpty 核对代转"拒绝结果保存失败"的返回：error 是
33	// 保存错误而非任何业务拒绝（含授权类的已撤销、已到期、已使用与账户停用
34	// 哨兵）；结果为空——不携带授权或藏品编号、前后持有人、版本、历史序号或
35	// 金额，业务错误为空，也不标记为重复返回。
36	func assertProxySaveFailureEmpty(t *testing.T, res ProxyTransferResult, err error) {
37		t.Helper()
38		assertSaveFailureError(t, err)
39		for _, s := range []error{
40			ErrAuthorizationRevoked, ErrAuthorizationExpired, ErrAuthorizationUsed,
41			ErrAccountInactive,
42		} {
43			if errors.Is(err, s) {
44				t.Fatalf("返回的应是保存错误，不能是业务拒绝 %v: %v", s, err)
45			}
46		}
47		if res.AuthID != "" || res.ItemID != "" || res.FromID != "" || res.ToID != "" ||
48			res.Version != 0 || res.TxSeq != 0 || res.Replayed || res.Err != nil ||
49			res.Price != 0 || res.Payables != nil || res.Remainder != 0 {
50			t.Fatalf("拒绝结果保存失败必须返回空结果: %+v", res)
51		}
52	}
53	
54	// assertProxyRequestFree 核对请求号未被这次未保存的拒绝占用（在同一个已
55	// 打开的登记册上检查）。
56	func assertProxyRequestFree(t *testing.T, r *Registry, req ProxyTransferRequest) {
57		t.Helper()
58		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
59			t.Fatalf("未保存的拒绝不应占用请求号 %s", req.RequestID)
60		}
61	}
62	
63	// assertProxyRequestSavedRejected 核对拒绝结果已按指定业务原因登记落盘。
64	func assertProxyRequestSavedRejected(t *testing.T, r *Registry, req ProxyTransferRequest, wantErr error) {
65		t.Helper()
66		prev, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]
67		if !ok {
68			t.Fatalf("拒绝保存成功后应登记请求结果，请求号 %s 却空闲", req.RequestID)
69		}
70		if !prev.Rejected || prev.Kind != "proxy_transfer" || prev.AuthID != req.AuthID {
71			t.Fatalf("登记的请求结果异常: %+v", prev)
72		}
73		if wantErr != nil && !errors.Is(codeErr(prev.Reason), wantErr) {
74			t.Fatalf("登记的拒绝原因为 %s，应对应 %v", prev.Reason, wantErr)
75		}
76	}
77	
78	// assertNoPayables 核对版税应付保持调用前内容（无新增应付）。
79	func assertNoPayables(t *testing.T, r *Registry) {
80		t.Helper()
81		for _, acct := range []string{"alice", "bob", "carol"} {
82			got, err := r.PayablesOf(acct)
83			if err != nil {
84				t.Fatalf("PayablesOf %s: %v", acct, err)
85			}
86			if len(got) != 0 {
87				t.Fatalf("未保存的拒绝不应新增版税应付，%s 却有 %+v", acct, got)
88			}
89		}
90	}
