92	// TestProxyTransferExpiredRejectSaveFailureThenRevoke 覆盖题目主路径：授权
93	// 到期后的代转拒绝在拒绝结果自身落盘失败时，返回实际保存错误与空结果，
94	// 请求号不被占用，授权内容、使用标记、授权变更记录、藏品持有、历史与版税
95	// 应付保持操作前状态（含"保存仍失败时再次提交"与"原数据暂时无法读取"两种
96	// 情形）。保存恢复后先有一次其他操作成功保存，也不能把这次未保存的拒绝带
97	// 入登记册；随后授权人撤销授权，原样重提必须按重提时状态返回已撤销（不标
98	// 回放、首次保存），此后原样重提才回放已撤销的拒绝。
99	func TestProxyTransferExpiredRejectSaveFailureThenRevoke(t *testing.T) {
100		r := mustCreate(t, tempDir(t))
101		authzWorld(t, r)
102		base := time.Unix(1_700_000_000, 0)
103		r.now = func() time.Time { return base }
104		createReq := createAuthReq(r, "a1", time.Hour) // 到期点 base+1h
105		if _, err := r.CreateAuthorization(createReq); err != nil {
106			t.Fatal(err)
107		}
108		// 越过到期点：代转应被到期拒绝。
109		r.now = func() time.Time { return base.Add(2 * time.Hour) }
110		req := proxyReq("bob", "a1", "p-exp")
111	
112		orig, err := os.ReadFile(dataFile(r.dir))
113		if err != nil {
114			t.Fatal(err)
115		}
116		blockBatchSave(t, r)
117	
118		// 拒绝结果落盘失败：返回保存错误与空结果。
119		res, err := r.ProxyTransfer(req)
120		assertProxySaveFailureEmpty(t, res, err)
121		assertProxyRequestFree(t, r, req)
122		a, _ := r.GetAuthorization("a1")
123		if a.Status != AuthExpired || a.UsedTxSeq != 0 || a.UsedAt != (time.Time{}) {
124			t.Fatalf("未保存的到期拒绝不应改变授权: %+v", a)
125		}
126		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 || evs[0].Kind != "create" {
127			t.Fatalf("未保存的到期拒绝不应新增授权变更记录: %+v", evs)
128		}
129		assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
130		assertNoPayables(t, r)
131	
132		// 保存条件未恢复时再次提交同一请求：仍重新尝试保存并失败，不能把上次
133		// 未保存的拒绝当成已保存拒绝回放。
134		res, err = r.ProxyTransfer(req)
135		assertProxySaveFailureEmpty(t, res, err)
136		assertProxyRequestFree(t, r, req)
137	
138		// 同时让原数据暂时无法读取（commit 无法按磁盘重建状态）：未保存的拒绝
139		// 仍不能留在当前已打开的登记册中。
140		if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
141			t.Fatal(err)
142		}
143		res, err = r.ProxyTransfer(req)
144		assertProxySaveFailureEmpty(t, res, err)
145		assertProxyRequestFree(t, r, req)
146		a, _ = r.GetAuthorization("a1")
147		if a.Status != AuthExpired || a.UsedTxSeq != 0 {
148			t.Fatalf("不可读磁盘失败后授权不应改变: %+v", a)
149		}
150		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 {
151			t.Fatalf("不可读磁盘失败后授权变更记录应只有创建: %+v", evs)
152		}
153		assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
154	
155		// 恢复正常读写；其他操作成功保存不能把这次未保存的拒绝带入登记册。
156		if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
157			t.Fatal(err)
158		}
159		restoreBatchSave(t, r)
160		if err := r.RegisterAccount("dave", "路人"); err != nil {
161			t.Fatal(err)
162		}
163		assertProxyRequestFree(t, r, req)
164		a, _ = r.GetAuthorization("a1")
165		if a.Status != AuthExpired {
166			t.Fatalf("其他操作保存后授权应仍只是到期、未终结: %+v", a)
167		}
168	
169		// 授权人完成撤销：业务状态从到期变为已撤销。
170		rv, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
171			Operator: "alice", Reason: "到期后撤销", RequestID: "rv-1", AuthID: "a1",
172		})
173		if err != nil || rv.Status != AuthRevoked {
174			t.Fatalf("授权人应能撤销到期未使用的授权: %+v, %v", rv, err)
175		}
176	
177		// 完全相同的代转请求按重提时状态重新判断：返回已撤销，首次重新处理不标
178		// 回放，结果带授权编号与业务错误，这次拒绝才首次落盘。
179		res, err = r.ProxyTransfer(req)
180		if !errors.Is(err, ErrAuthorizationRevoked) {
181			t.Fatalf("重提应按当前状态返回 ErrAuthorizationRevoked: %v", err)
182		}
183		if res.Replayed || res.AuthID != "a1" || !errors.Is(res.Err, ErrAuthorizationRevoked) ||
184			res.ItemID != "" || res.TxSeq != 0 {
185			t.Fatalf("已撤销拒绝的重提结果异常: %+v", res)
186		}
187		assertProxyRequestSavedRejected(t, r, req, ErrAuthorizationRevoked)
188		// 拒绝仍不改变持有、授权使用标记与历史。
189		a, _ = r.GetAuthorization("a1")
190		if a.Status != AuthRevoked || a.UsedTxSeq != 0 {
191			t.Fatalf("已撤销拒绝不应把授权用掉: %+v", a)
192		}
193		assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
194	
195		// 此后原样重提才回放已保存的已撤销拒绝。
196		res, err = r.ProxyTransfer(req)
197		if !errors.Is(err, ErrAuthorizationRevoked) || !res.Replayed ||
198			res.AuthID != "a1" || !errors.Is(res.Err, ErrAuthorizationRevoked) {
199			t.Fatalf("保存后的重提应回放已撤销拒绝: %+v, err %v", res, err)
200		}
201	}
