203	// TestProxyTransferStateRejectSaveFailureVariants 逐类覆盖无权、已使用、
204	// 账户停用与持有版本已变化四种状态类拒绝：保存失败时返回保存错误与空结果，
205	// 请求号不被占用，授权、授权变更记录、藏品持有、历史与版税应付保持操作前
206	// 状态；保存恢复且拒绝条件仍在时，原请求重提先成功保存此次拒绝再返回对应
207	// 业务错误（首次不标回放），此后完全相同的提交才回放它。
208	func TestProxyTransferStateRejectSaveFailureVariants(t *testing.T) {
209		t.Run("forbidden", func(t *testing.T) {
210			r := mustCreate(t, tempDir(t))
211			authzWorld(t, r)
212			if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
213				t.Fatal(err)
214			}
215			// 操作者 alice 不是受托人 bob：ErrForbidden。
216			req := proxyReq("alice", "a1", "p-forbidden")
217	
218			blockBatchSave(t, r)
219			res, err := r.ProxyTransfer(req)
220			assertProxySaveFailureEmpty(t, res, err)
221			assertProxyRequestFree(t, r, req)
222			if a, _ := r.GetAuthorization("a1"); a.Status != AuthActive || a.UsedTxSeq != 0 {
223				t.Fatalf("未保存的无权拒绝不应改变授权: %+v", a)
224			}
225			if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 {
226				t.Fatalf("未保存的无权拒绝不应新增授权变更记录: %+v", evs)
227			}
228			assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
229	
230			restoreBatchSave(t, r)
231			res, err = r.ProxyTransfer(req)
232			if !errors.Is(err, ErrForbidden) || res.Replayed || res.AuthID != "a1" ||
233				!errors.Is(res.Err, ErrForbidden) {
234				t.Fatalf("重提应在保存成功后返回 ErrForbidden: %+v, err %v", res, err)
235			}
236			assertProxyRequestSavedRejected(t, r, req, ErrForbidden)
237			res, err = r.ProxyTransfer(req)
238			if !errors.Is(err, ErrForbidden) || !res.Replayed {
239				t.Fatalf("再次提交应回放已保存的无权拒绝: %+v, err %v", res, err)
240			}
241		})
242	
243		t.Run("used", func(t *testing.T) {
244			r := mustCreate(t, tempDir(t))
245			setupUsedAuthzWorld(t, r)
246			// a2 已由 bob 代转给 carol：i1 在 carol 手中版本 2，a2 已使用。
247			req := proxyReq("bob", "a2", "p-used")
248	
249			blockBatchSave(t, r)
250			res, err := r.ProxyTransfer(req)
251			assertProxySaveFailureEmpty(t, res, err)
252			assertProxyRequestFree(t, r, req)
253			a, _ := r.GetAuthorization("a2")
254			if a.Status != AuthUsed || a.UsedTxSeq != 2 {
255				t.Fatalf("未保存的拒绝不应改变已使用授权: %+v", a)
256			}
257			if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 ||
258				evs[2].Kind != "use" || evs[2].AuthID != "a2" {
259				t.Fatalf("授权变更记录应保持操作前的 3 条: %+v", evs)
260			}
261			assertHoldingUnchanged(t, r, "i1", "carol", 2, 2)
262	
263			restoreBatchSave(t, r)
264			res, err = r.ProxyTransfer(req)
265			if !errors.Is(err, ErrAuthorizationUsed) || res.Replayed || res.AuthID != "a2" ||
266				!errors.Is(res.Err, ErrAuthorizationUsed) {
267				t.Fatalf("重提应在保存成功后返回 ErrAuthorizationUsed: %+v, err %v", res, err)
268			}
269			assertProxyRequestSavedRejected(t, r, req, ErrAuthorizationUsed)
270			a, _ = r.GetAuthorization("a2")
271			if a.Status != AuthUsed || a.UsedTxSeq != 2 {
272				t.Fatalf("已使用拒绝不应改变授权: %+v", a)
273			}
274			res, err = r.ProxyTransfer(req)
275			if !errors.Is(err, ErrAuthorizationUsed) || !res.Replayed {
276				t.Fatalf("再次提交应回放已保存的已使用拒绝: %+v, err %v", res, err)
277			}
278		})
279	
280		t.Run("inactive", func(t *testing.T) {
281			r := mustCreate(t, tempDir(t))
282			authzWorld(t, r)
283			if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
284				t.Fatal(err)
285			}
286			// 接收人停用：ErrAccountInactive。
287			if err := r.DeactivateAccount("carol"); err != nil {
288				t.Fatal(err)
289			}
290			req := proxyReq("bob", "a1", "p-inactive")
291	
292			blockBatchSave(t, r)
293			res, err := r.ProxyTransfer(req)
294			assertProxySaveFailureEmpty(t, res, err)
295			assertProxyRequestFree(t, r, req)
296			if a, _ := r.GetAuthorization("a1"); a.Status != AuthActive || a.UsedTxSeq != 0 {
297				t.Fatalf("未保存的停用拒绝不应改变授权: %+v", a)
298			}
299			assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
300	
301			restoreBatchSave(t, r)
302			res, err = r.ProxyTransfer(req)
303			if !errors.Is(err, ErrAccountInactive) || res.Replayed || res.AuthID != "a1" ||
304				!errors.Is(res.Err, ErrAccountInactive) {
305				t.Fatalf("重提应在保存成功后返回 ErrAccountInactive: %+v, err %v", res, err)
306			}
307			assertProxyRequestSavedRejected(t, r, req, ErrAccountInactive)
308			res, err = r.ProxyTransfer(req)
309			if !errors.Is(err, ErrAccountInactive) || !res.Replayed {
310				t.Fatalf("再次提交应回放已保存的停用拒绝: %+v, err %v", res, err)
311			}
312		})
313	
314		t.Run("conflict", func(t *testing.T) {
315			r := mustCreate(t, tempDir(t))
316			authzWorld(t, r)
317			if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
318				t.Fatal(err)
319			}
320			// 持有人另作直接转让：i1 变为 bob 版本 2，授权绑定的 alice 版本 1
321			// 已不匹配：ErrConflict（藏品即使之后回到 alice 手中也不恢复）。
322			if _, err := r.Transfer(xferReq("alice", "i1", "bob", 1, "direct-1")); err != nil {
323				t.Fatal(err)
324			}
325			req := proxyReq("bob", "a1", "p-conflict")
326	
327			blockBatchSave(t, r)
328			res, err := r.ProxyTransfer(req)
329			assertProxySaveFailureEmpty(t, res, err)
330			assertProxyRequestFree(t, r, req)
331			if a, _ := r.GetAuthorization("a1"); a.Status != AuthActive || a.UsedTxSeq != 0 {
332				t.Fatalf("未保存的版本冲突拒绝不应改变授权: %+v", a)
333			}
334			assertHoldingUnchanged(t, r, "i1", "bob", 2, 2)
335	
336			restoreBatchSave(t, r)
337			res, err = r.ProxyTransfer(req)
338			if !errors.Is(err, ErrConflict) || res.Replayed || res.AuthID != "a1" ||
339				!errors.Is(res.Err, ErrConflict) {
340				t.Fatalf("重提应在保存成功后返回 ErrConflict: %+v, err %v", res, err)
341			}
342			assertProxyRequestSavedRejected(t, r, req, ErrConflict)
343			res, err = r.ProxyTransfer(req)
344			if !errors.Is(err, ErrConflict) || !res.Replayed {
345				t.Fatalf("再次提交应回放已保存的版本冲突拒绝: %+v, err %v", res, err)
346			}
347		})
348	}
