350	// TestProxyTransferRejectSaveFailureUnreadableDisk 覆盖：拒绝结果保存失败且
351	// 原数据暂时无法读取（commit 无法按磁盘重建状态）时，未保存的拒绝也不能
352	// 留在当前已打开的登记册中；恢复正常读写后其他操作成功保存不带入这次拒绝，
353	// 原请求重提才首次保存对应业务拒绝，再次提交才回放。已使用与无权两种拒绝
354	// 分别覆盖。
355	func TestProxyTransferRejectSaveFailureUnreadableDisk(t *testing.T) {
356		t.Run("used", func(t *testing.T) {
357			r := mustCreate(t, tempDir(t))
358			setupUsedAuthzWorld(t, r)
359			req := proxyReq("bob", "a2", "p-used")
360	
361			orig, err := os.ReadFile(dataFile(r.dir))
362			if err != nil {
363				t.Fatal(err)
364			}
365			blockBatchSave(t, r)
366			if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
367				t.Fatal(err)
368			}
369	
370			res, err := r.ProxyTransfer(req)
371			assertProxySaveFailureEmpty(t, res, err)
372			assertProxyRequestFree(t, r, req)
373			a, _ := r.GetAuthorization("a2")
374			if a.Status != AuthUsed || a.UsedTxSeq != 2 {
375				t.Fatalf("不可读磁盘失败后已使用授权不应改变: %+v", a)
376			}
377			if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 {
378				t.Fatalf("不可读磁盘失败后授权变更记录应保持 3 条: %+v", evs)
379			}
380			assertHoldingUnchanged(t, r, "i1", "carol", 2, 2)
381	
382			if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
383				t.Fatal(err)
384			}
385			restoreBatchSave(t, r)
386			if err := r.RegisterAccount("dave", "路人"); err != nil {
387				t.Fatal(err)
388			}
389			assertProxyRequestFree(t, r, req)
390	
391			res, err = r.ProxyTransfer(req)
392			if !errors.Is(err, ErrAuthorizationUsed) || res.Replayed ||
393				!errors.Is(res.Err, ErrAuthorizationUsed) || res.AuthID != "a2" {
394				t.Fatalf("恢复后重提应首次保存已使用拒绝: %+v, err %v", res, err)
395			}
396			res, err = r.ProxyTransfer(req)
397			if !errors.Is(err, ErrAuthorizationUsed) || !res.Replayed {
398				t.Fatalf("再次提交应回放已保存的已使用拒绝: %+v, err %v", res, err)
399			}
400		})
401	
402		t.Run("forbidden", func(t *testing.T) {
403			r := mustCreate(t, tempDir(t))
404			authzWorld(t, r)
405			if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
406				t.Fatal(err)
407			}
408			req := proxyReq("alice", "a1", "p-forbidden")
409	
410			orig, err := os.ReadFile(dataFile(r.dir))
411			if err != nil {
412				t.Fatal(err)
413			}
414			blockBatchSave(t, r)
415			if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
416				t.Fatal(err)
417			}
418	
419			res, err := r.ProxyTransfer(req)
420			assertProxySaveFailureEmpty(t, res, err)
421			assertProxyRequestFree(t, r, req)
422			if a, _ := r.GetAuthorization("a1"); a.Status != AuthActive {
423				t.Fatalf("不可读磁盘失败后授权不应改变: %+v", a)
424			}
425			assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
426	
427			if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
428				t.Fatal(err)
429			}
430			restoreBatchSave(t, r)
431			if err := r.RegisterAccount("dave", "路人"); err != nil {
432				t.Fatal(err)
433			}
434			assertProxyRequestFree(t, r, req)
435	
436			res, err = r.ProxyTransfer(req)
437			if !errors.Is(err, ErrForbidden) || res.Replayed ||
438				!errors.Is(res.Err, ErrForbidden) {
439				t.Fatalf("恢复后重提应首次保存无权拒绝: %+v, err %v", res, err)
440			}
441			res, err = r.ProxyTransfer(req)
442			if !errors.Is(err, ErrForbidden) || !res.Replayed {
443				t.Fatalf("再次提交应回放已保存的无权拒绝: %+v, err %v", res, err)
444			}
445		})
446	}
447	
448	// TestProxyTransferFailedSaveRequestIDReusable 覆盖：保存失败的拒绝不占用
449	// 请求号——同一受托人用同一请求号对另一份仍可用的授权发起代转时不能遭遇
450	// 请求号冲突，应正常成功且不标回放；只有实际保存过的结果才继续适用原有的
451	// 同号不同参数冲突规则。
452	func TestProxyTransferFailedSaveRequestIDReusable(t *testing.T) {
453		r := mustCreate(t, tempDir(t))
454		authzWorld(t, r)
455		// a1 绑定 i1；另发行 i2 并创建 a2，先把 a2 用掉（i2 转到 carol 手中，
456		// 版本 2），a1 与 i1 不受影响、仍可使用。
457		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
458			t.Fatal(err)
459		}
460		if _, err := r.Issue(issueReq("i2", "alice")); err != nil {
461			t.Fatal(err)
462		}
463		a2req := CreateAuthorizationRequest{
464			Operator: "alice", Reason: "委托代转", RequestID: "create-a2",
465			AuthID: "a2", ItemID: "i2", TrusteeID: "bob", ToID: "carol",
466			ExpectedOwner: "alice", ExpectedVer: 1, ExpiresAt: r.now().Add(time.Hour),
467		}
468		if _, err := r.CreateAuthorization(a2req); err != nil {
469			t.Fatal(err)
470		}
471		if _, err := r.ProxyTransfer(proxyReq("bob", "a2", "p-a2")); err != nil {
472			t.Fatal(err)
473		}
474	
475		// bob 对已使用的 a2 代转将被拒绝；同一请求号稍后改用于仍有效的 a1。
476		failedReq := proxyReq("bob", "a2", "p-x")
477		otherReq := proxyReq("bob", "a1", "p-x")
478	
479		blockBatchSave(t, r)
480		res, err := r.ProxyTransfer(failedReq)
481		assertProxySaveFailureEmpty(t, res, err)
482		assertProxyRequestFree(t, r, failedReq)
483		// i1 仍属 alice 版本 1，a1 仍可用。
484		assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
485	
486		// 保存条件未恢复时重放原失败请求：仍只失败在保存上。
487		res, err = r.ProxyTransfer(failedReq)
488		assertProxySaveFailureEmpty(t, res, err)
489		assertProxyRequestFree(t, r, failedReq)
490	
491		// 保存恢复后，同一受托人用同一请求号代转另一份仍有效的授权：未保存的
492		// 拒绝不适用冲突规则，请求正常成功且不标回放。
493		restoreBatchSave(t, r)
494		res, err = r.ProxyTransfer(otherReq)
495		if err != nil {
496			t.Fatalf("未保存的拒绝不应阻碍同号代转另一份有效授权: %v", err)
497		}
498		if res.Replayed || res.Err != nil || res.AuthID != "a1" || res.ItemID != "i1" ||
499			res.FromID != "alice" || res.ToID != "carol" || res.Version != 2 {
500			t.Fatalf("同号代转另一份授权的结果异常: %+v", res)
501		}
502		h, _ := r.GetHolding("i1")
503		if h.OwnerID != "carol" || h.Version != 2 {
504			t.Fatalf("a1 代转应正常完成: %+v", h)
505		}
506		a1, _ := r.GetAuthorization("a1")
507		if a1.Status != AuthUsed || a1.UsedTxSeq != res.TxSeq {
508			t.Fatalf("a1 应记为本次代转已使用: %+v", a1)
509		}
510	
511		// 请求号此刻已被实际保存的 a1 成功结果占用：同号不同参数（改用 a2）按
512		// 原有规则返回 ErrRequestConflict。
513		if _, err := r.ProxyTransfer(failedReq); !errors.Is(err, ErrRequestConflict) {
514			t.Fatalf("实际保存过的结果才应触发同号不同参数冲突: %v", err)
515		}
516		// 完全相同的已保存请求（代转 a1）回放首次成功结果。
517		res, err = r.ProxyTransfer(otherReq)
518		if err != nil || !res.Replayed || res.AuthID != "a1" || res.ToID != "carol" {
519			t.Fatalf("已保存的同号成功结果应被回放: %+v, err %v", res, err)
520		}
521	}
522	
523	// TestProxyTransferRejectSaveFailureAfterReopen 覆盖磁盘视角：原数据可读时
524	// 拒绝结果保存失败后关闭重开，看到的仍是拒绝前状态——授权未改变、请求号
525	// 未占用；恢复保存后用原请求重提才首次保存该拒绝，再次提交回放。
526	func TestProxyTransferRejectSaveFailureAfterReopen(t *testing.T) {
527		dir := tempDir(t)
528		r := mustCreate(t, dir)
529		authzWorld(t, r)
530		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
531			t.Fatal(err)
532		}
533		// alice 不是受托人：ErrForbidden。
534		req := proxyReq("alice", "a1", "pf")
535	
536		blockBatchSave(t, r)
537		res, err := r.ProxyTransfer(req)
538		assertProxySaveFailureEmpty(t, res, err)
539	
540		if err := r.Close(); err != nil {
541			t.Fatal(err)
542		}
543		r2, err := Open(dir)
544		if err != nil {
545			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
546		}
547		t.Cleanup(func() { _ = r2.Close() })
548		if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
549			t.Fatal("重开后未保存的拒绝不应占用请求号")
550		}
551		if a, _ := r2.GetAuthorization("a1"); a.Status != AuthActive || a.UsedTxSeq != 0 {
552			t.Fatalf("重开后授权应仍有效且未使用: %+v", a)
553		}
554		if evs, _ := r2.AuthorizationHistory("i1"); len(evs) != 1 {
555			t.Fatalf("重开后授权变更记录应只有创建: %+v", evs)
556		}
557		assertHoldingUnchanged(t, r2, "i1", "alice", 1, 1)
558	
559		restoreBatchSave(t, r2)
560		res2, err := r2.ProxyTransfer(req)
561		if !errors.Is(err, ErrForbidden) || res2.Replayed ||
562			!errors.Is(res2.Err, ErrForbidden) || res2.AuthID != "a1" {
563			t.Fatalf("重开后重提应首次保存无权拒绝: %+v, err %v", res2, err)
564		}
565		res2, err = r2.ProxyTransfer(req)
566		if !errors.Is(err, ErrForbidden) || !res2.Replayed {
567			t.Fatalf("再次提交应回放已保存的无权拒绝: %+v, err %v", res2, err)
568		}
569	}
570	
571	// TestProxyTransferValidationIgnoresSaveFailure 覆盖：必填内容缺失与引用
572	// 不存在（授权不存在、受托人未登记）的请求直接按原错误拒绝、不占用请求号、
573	// 不要求保存，即使数据位置暂时不可写也仍返回原参数/引用错误，不能改报保存
574	// 错误。
575	func TestProxyTransferValidationIgnoresSaveFailure(t *testing.T) {
576		r := mustCreate(t, tempDir(t))
577		authzWorld(t, r)
578		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
579			t.Fatal(err)
580		}
581	
582		blockBatchSave(t, r)
583		defer restoreBatchSave(t, r)
584	
585		// 必填内容缺失：返回 ErrInvalidArgument，不是保存错误。
586		if _, err := r.ProxyTransfer(ProxyTransferRequest{}); !errors.Is(err, ErrInvalidArgument) {
587			t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
588		}
589		missing := proxyReq("bob", "a1", "p-miss")
590		missing.AuthID = ""
591		if _, err := r.ProxyTransfer(missing); !errors.Is(err, ErrInvalidArgument) {
592			t.Fatalf("必填缺失应返回 ErrInvalidArgument: %v", err)
593		}
594	
595		// 授权不存在：返回 ErrNotFound（结果带授权编号与业务错误），不是保存
596		// 错误，也不占用请求号。
597		notFoundReq := proxyReq("bob", "ghost", "p-nf")
598		res, err := r.ProxyTransfer(notFoundReq)
599		if !errors.Is(err, ErrNotFound) {
600			t.Fatalf("授权不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
601		}
602		if res.AuthID != "ghost" || !errors.Is(res.Err, ErrNotFound) || res.Replayed {
603			t.Fatalf("授权不存在的结果异常: %+v", res)
604		}
605		assertProxyRequestFree(t, r, notFoundReq)
606	
607		// 受托人未登记：同样是引用不存在，返回 ErrNotFound 且不占用请求号。
608		noOperatorReq := proxyReq("dave", "a1", "p-nop")
609		res, err = r.ProxyTransfer(noOperatorReq)
610		if !errors.Is(err, ErrNotFound) {
611			t.Fatalf("受托人未登记应返回 ErrNotFound，不能改报保存错误: %v", err)
612		}
613		if res.AuthID != "a1" || !errors.Is(res.Err, ErrNotFound) || res.Replayed {
614			t.Fatalf("受托人未登记的结果异常: %+v", res)
615		}
616		assertProxyRequestFree(t, r, noOperatorReq)
617	
618		// 保存条件恢复后，同一受托人用同一请求号对真实授权发起代转应正常成功：
619		// 引用不存在没有占用请求号。
620		restoreBatchSave(t, r)
621		sameIDRealAuth := proxyReq("bob", "a1", "p-nf")
622		res, err = r.ProxyTransfer(sameIDRealAuth)
623		if err != nil || res.Replayed || res.Err != nil || res.AuthID != "a1" ||
624			res.ToID != "carol" || res.Version != 2 {
625			t.Fatalf("引用不存在不应占用请求号，同号代转真实授权应成功: %+v, err %v", res, err)
626		}
627	}
628	
629	// TestProxyTransferSavedRejectionReplaysAndConflicts 覆盖保存成功后的既有
630	// 幂等语义不变：到期拒绝保存后，完全相同的请求回放首次拒绝（即使授权随后
631	// 被撤销也仍回放到期，而非改判已撤销），改动原因则按请求号冲突拒绝。
632	func TestProxyTransferSavedRejectionReplaysAndConflicts(t *testing.T) {
633		r := mustCreate(t, tempDir(t))
634		authzWorld(t, r)
635		createReq := createAuthReq(r, "a1", time.Minute)
636		if _, err := r.CreateAuthorization(createReq); err != nil {
637			t.Fatal(err)
638		}
639		r.now = func() time.Time { return createReq.ExpiresAt.Add(time.Second) }
640		req := proxyReq("bob", "a1", "late")
641	
642		// 首次：到期拒绝并成功保存。
643		res, err := r.ProxyTransfer(req)
644		if !errors.Is(err, ErrAuthorizationExpired) || res.Replayed ||
645			res.AuthID != "a1" || !errors.Is(res.Err, ErrAuthorizationExpired) {
646			t.Fatalf("首次代转应返回未回放的到期拒绝: %+v, err %v", res, err)
647		}
648		assertProxyRequestSavedRejected(t, r, req, ErrAuthorizationExpired)
649	
650		// 完全相同的请求重提：回放首次到期拒绝。
651		res, err = r.ProxyTransfer(req)
652		if !errors.Is(err, ErrAuthorizationExpired) || !res.Replayed ||
653			!errors.Is(res.Err, ErrAuthorizationExpired) {
654			t.Fatalf("相同请求应回放首次到期拒绝: %+v, err %v", res, err)
655		}
656	
657		// 改动该请求的业务内容（原因）：请求号冲突。
658		changed := req
659		changed.Reason = "换个原因"
660		if _, err := r.ProxyTransfer(changed); !errors.Is(err, ErrRequestConflict) {
661			t.Fatalf("改动业务内容应返回 ErrRequestConflict: %v", err)
662		}
663	
664		// 授权随后被撤销：原请求仍回放保存过的到期拒绝，而不是改判已撤销。
665		r.now = func() time.Time { return createReq.ExpiresAt.Add(2 * time.Second) }
666		if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
667			Operator: "alice", Reason: "撤销", RequestID: "rv", AuthID: "a1",
668		}); err != nil {
669			t.Fatal(err)
670		}
671		res, err = r.ProxyTransfer(req)
672		if !errors.Is(err, ErrAuthorizationExpired) || !res.Replayed {
673			t.Fatalf("授权撤销后原请求仍应回放到期拒绝: %+v, err %v", res, err)
674		}
675	}
