1	package registry
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Registry 是一个已打开的本地登记册。同一目录同时只能被一个 Registry
15	// 独占打开（目录内 flock）；单个 Registry 的方法可被多个 goroutine
16	// 并发调用，所有状态变更与落盘在同一把互斥锁内一次完成。
17	type Registry struct {
18		dir    string
19		store  *store
20		state  *snapshot
21		mu     sync.Mutex
22		closed bool
23		// now 返回当前时间，到期判断以此为准；生产环境为 time.Now，测试可替换。
24		now func() time.Time
25	}
26	
27	// Create 在 dir 新建并打开一个空登记册。调用者通过 dir 指定本机数据
28	// 位置；目录不存在会被创建。目录中已存在登记册数据时返回错误，
29	// 已有的数据不会被覆盖。
30	func Create(dir string) (*Registry, error) {
31		if strings.TrimSpace(dir) == "" {
32			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
33		}
34		if err := os.MkdirAll(dir, dirMode); err != nil {
35			return nil, fmt.Errorf("registry: 无法创建数据目录: %w", err)
36		}
37		if _, err := os.Stat(dataFile(dir)); err == nil {
38			return nil, fmt.Errorf("%w: %s 已存在登记册数据，应用 Open 打开", ErrAlreadyExists, dir)
39		} else if !errors.Is(err, os.ErrNotExist) {
40			return nil, fmt.Errorf("registry: 无法访问数据目录: %w", err)
41		}
42		lock, err := acquireLock(dir)
43		if err != nil {
44			return nil, err
45		}
46		// 取锁后再确认一次，避免与另一个进程的 Create 竞争。
47		if _, err := os.Stat(dataFile(dir)); err == nil {
48			_ = releaseLock(lock)
49			return nil, fmt.Errorf("%w: %s 已存在登记册数据", ErrAlreadyExists, dir)
50		}
51		st := &store{dir: dir, lock: lock}
52		s := newSnapshot()
53		if err := st.save(s); err != nil {
54			_ = releaseLock(lock)
55			return nil, err
56		}
57		return &Registry{dir: dir, store: st, state: s, now: time.Now}, nil
58	}
59	
60	// Open 打开 dir 中的已有登记册。数据文件缺失视为空目录的新建场景，
61	// 应使用 Create；数据存在但无法读取或解析时返回包裹 ErrCorrupt 的
62	// 错误，不会被静默当成空登记册。
63	func Open(dir string) (*Registry, error) {
64		if strings.TrimSpace(dir) == "" {
65			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
66		}
67		if info, err := os.Stat(dir); err != nil {
68			return nil, fmt.Errorf("registry: 无法打开数据目录: %w", err)
69		} else if !info.IsDir() {
70			return nil, fmt.Errorf("%w: %s 不是目录", ErrInvalidArgument, dir)
71		}
72		lock, err := acquireLock(dir)
73		if err != nil {
74			return nil, err
75		}
76		// 数据文件不存在不是"空登记册"：明确报错，提示用 Create 新建，
77		// 绝不把无数据目录静默当成空登记册。
78		if _, err := os.Stat(dataFile(dir)); err != nil {
79			_ = releaseLock(lock)
80			if errors.Is(err, os.ErrNotExist) {
81				return nil, fmt.Errorf("%w: %s 中没有登记册数据，请用 Create 新建", ErrNotFound, dir)
82			}
83			return nil, fmt.Errorf("registry: 无法访问登记册数据: %w", err)
84		}
85		s, err := load(dir)
86		if err != nil {
87			_ = releaseLock(lock)
88			return nil, err
89		}
90		return &Registry{dir: dir, store: &store{dir: dir, lock: lock}, state: s, now: time.Now}, nil
91	}
92	
93	// Close 正常关闭登记册并释放独占锁。关闭后不能再调用其他方法。
94	func (r *Registry) Close() error {
95		r.mu.Lock()
96		defer r.mu.Unlock()
97		if r.closed {
98			return nil
99		}
100		r.closed = true
101		return releaseLock(r.store.lock)
102	}
103	
104	func releaseLock(f *os.File) error {
105		err := f.Close() // Close 同时释放 flock
106		if err != nil {
107			return fmt.Errorf("registry: 关闭登记册失败: %w", err)
108		}
109		return nil
110	}
111	
112	func (r *Registry) checkOpen() error {
113		if r.closed {
114			return fmt.Errorf("registry: 登记册已关闭")
115		}
116		return nil
117	}
118	
119	// commit 将当前状态原子落盘；落盘失败时以磁盘内容为准重新加载，
120	// 避免内存状态与已持久化状态不一致。
121	func (r *Registry) commit() error {
122		if err := r.store.save(r.state); err != nil {
123			if s, lerr := load(r.dir); lerr == nil {
124				r.state = s
125			}
126			return err
127		}
128		return nil
129	}
130	
131	// ---- 账户 ----
132	
133	// RegisterAccount 以唯一编号登记账户，登记后即为可用状态。
134	//
135	// 登记以一次保存完成为准：新账户尚未原子替换原数据就发生保存错误（如数据
136	// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功或编号冲突，也
137	// 不能用失败后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法
138	// 读取或解析、状态未能按磁盘重建，同一个仍打开的登记册也必须立即表现为该
139	// 编号从未登记：GetAccount 返回 ErrNotFound，藏品转让不能把它当成已登记的
140	// 接收账户；失败不占用新账户编号，保存条件未恢复时用该编号再次登记仍实际
141	// 尝试保存并返回当次保存错误，而不是因遗留账户返回 ErrAlreadyExists。原
142	// 数据仍可读取的普通保存失败同样撤销本次登记，不依赖重新读取成功。随后另
143	// 一次无关操作成功保存也不会把这个未保存的账户夹带落盘，关闭再打开登记册
144	// 后它仍不存在。读写恢复后用该编号重新登记，以本次提交的元数据为准，保存
145	// 成功才显示为可用账户。此前成功登记的账户及其元数据、可用或停用状态，以及
146	// 已有藏品的持有人、版本与历史都原样保留。空白编号仍返回 ErrInvalidArgument，
147	// 元数据允许为空；已成功登记的编号无论账户是否停用都返回 ErrAlreadyExists、
148	// 不覆盖其记录，这些业务拒绝不因数据位置恰好不可写而变成保存错误。
149	func (r *Registry) RegisterAccount(id, metadata string) error {
150		r.mu.Lock()
151		defer r.mu.Unlock()
152		if err := r.checkOpen(); err != nil {
153			return err
154		}
155		if strings.TrimSpace(id) == "" {
156			return fmt.Errorf("%w: 账户编号不能为空", ErrInvalidArgument)
157		}
158		if _, ok := r.state.Accounts[id]; ok {
159			return fmt.Errorf("%w: 账户 %s", ErrAlreadyExists, id)
160		}
161		r.state.Accounts[id] = account{ID: id, Metadata: metadata, Active: true}
162		if err := r.commit(); err != nil {
163			// commit 失败时已尝试按磁盘内容重建状态：重建成功则新账户已随旧
164			// 状态整体消失，删除是无害的兜底；磁盘暂时不可读、状态未能重建时
165			// 新账户仍在，显式删除，让当前仍打开的登记册表现为该编号从未登记
166			// ——GetAccount 返回 ErrNotFound、转让不把它当成已登记的接收账户、
167			// 再次登记不会撞上遗留的 ErrAlreadyExists，也不被随后另一次成功
168			// 保存夹带落盘。返回实际写入错误，而非成功、编号冲突或重新读取时
169			// 的错误。
170			delete(r.state.Accounts, id)
171			return err
172		}
173		return nil
174	}
175	
176	// DeactivateAccount 停用账户。停用后其原有藏品与历史仍可查询，但不能
177	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
178	//
179	// 停用以保存成功为准：停用状态尚未原子替换原数据就发生写入错误（如数据
180	// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功，也不能用失败
181	// 后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法读取或解析、
182	// 状态未能按磁盘重建，同一个仍打开的登记册也必须保持停用前的样子：该账户
183	// 仍可用，编号与元数据不变，其已有藏品的持有人、版本与历史原样保留；其他
184	// 账户此前已经成功停用的状态不被恢复为可用。原数据仍可读取的普通保存失败
185	// 同样撤销本次变化，不依赖重新读取成功。随后另一次无关操作成功保存也不会
186	// 把这次未保存的停用夹带落盘。保存条件恢复后该账户仍按原有规则参与转让；
187	// 之后再次提交停用须重新完成保存，成功返回后才显示不可用，并按现有规则
188	// 拒绝其发起或接收新的转让。
189	func (r *Registry) DeactivateAccount(id string) error {
190		r.mu.Lock()
191		defer r.mu.Unlock()
192		if err := r.checkOpen(); err != nil {
193			return err
194		}
195		a, ok := r.state.Accounts[id]
196		if !ok {
197			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
198		}
199		if !a.Active {
200			return nil // 停用是幂等的终态，已停用直接成功，不要求再次写入
201		}
202		// 保存停用前的账户记录：停用以一次保存完成为准。commit 失败且磁盘
203		// 暂时不可读、状态未能按磁盘重建时据此显式撤销，否则这次未保存的停用
204		// 会留在当前已打开的登记册中（GetAccount 显示不可用、转让被按停用
205		// 拒绝），并被随后另一次成功保存夹带落盘。
206		prev := a
207		a.Active = false
208		r.state.Accounts[id] = a
209		if err := r.commit(); err != nil {
210			// commit 失败时已尝试按磁盘内容重建状态：重建成功则账户已随旧状态
211			// 整体恢复可用，写回的记录与磁盘一致；磁盘暂时不可读、状态未能重建
212			// 时本次停用仍在，显式恢复为停用前记录，藏品持有、版本与历史本就未
213			// 被触碰。返回实际写入错误，而非成功或重新读取时的错误。
214			r.state.Accounts[id] = prev
215			return err
216		}
217		return nil
218	}
219	
220	// GetAccount 查询账户；账户不存在时返回包裹 ErrNotFound 的错误。
221	func (r *Registry) GetAccount(id string) (Account, error) {
222		r.mu.Lock()
223		defer r.mu.Unlock()
224		if err := r.checkOpen(); err != nil {
225			return Account{}, err
226		}
227		a, ok := r.state.Accounts[id]
228		if !ok {
229			return Account{}, fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
230		}
231		return Account{ID: a.ID, Metadata: a.Metadata, Active: a.Active}, nil
232	}
233	
234	// ---- 系列 ----
235	
236	// CreateSeries 登记一个系列，记录创建账户与文字元数据。创建账户必须
237	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
238	//
239	// 登记以一次保存完成为准：新系列尚未原子替换原数据就发生保存错误（如数据
240	// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功或编号冲突，也
241	// 不能用失败后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法
242	// 读取或解析、状态未能按磁盘重建，同一个仍打开的登记册也必须立即表现为该
243	// 编号从未登记：GetSeries 返回 ErrNotFound，不能把它当成已存在的系列继续
244	// 发行或封存；失败不占用系列编号，保存条件未恢复时用该编号再次登记仍实际
245	// 尝试保存并返回当次保存错误，而不是因遗留系列返回 ErrAlreadyExists。原
246	// 数据仍可读取的普通保存失败同样撤销本次登记，不依赖重新读取成功。随后另
247	// 一次无关操作成功保存也不会把这个未保存的系列夹带落盘，关闭再打开登记册
248	// 后它仍不存在。读写恢复后用该编号重新登记，以本次提交的创建账户与文字元
249	// 数据为准，保存成功才显示为未封存的新系列，并可按已有规则发行藏品。此前
250	// 成功登记的账户、系列及其封存状态，以及已有藏品的持有人、版本与历史都原
251	// 样保留。空白编号返回 ErrInvalidArgument，元数据允许为空；创建账户不存
252	// 在或已停用分别返回 ErrNotFound、ErrAccountInactive；已成功登记的系列编号
253	// 返回 ErrAlreadyExists、不覆盖其创建账户、元数据或封存状态，这些业务拒绝
254	// 不因数据位置恰好不可写而变成保存错误。
255	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
256		r.mu.Lock()
257		defer r.mu.Unlock()
258		if err := r.checkOpen(); err != nil {
259			return err
260		}
261		if strings.TrimSpace(id) == "" {
262			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
263		}
264		creator, ok := r.state.Accounts[creatorID]
265		if !ok {
266			return fmt.Errorf("%w: 创建账户 %s", ErrNotFound, creatorID)
267		}
268		if !creator.Active {
269			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
270		}
271		if _, ok := r.state.Series[id]; ok {
272			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
273		}
274		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
275		if err := r.commit(); err != nil {
276			// commit 失败时已尝试按磁盘内容重建状态：重建成功则新系列已随旧
277			// 状态整体消失，删除是无害的兜底；磁盘暂时不可读、状态未能重建时
278			// 新系列仍在，显式删除，让当前仍打开的登记册表现为该编号从未登记
279			// ——GetSeries 返回 ErrNotFound、发行与封存不把它当成已存在的系列、
280			// 再次登记不会撞上遗留的 ErrAlreadyExists，也不被随后另一次成功
281			// 保存夹带落盘。返回实际写入错误，而非成功、编号冲突或重新读取时
282			// 的错误。
283			delete(r.state.Series, id)
284			return err
285		}
286		return nil
287	}
288	
289	// SealSeries 封存系列。只有系列创建账户可以封存；封存后不能继续发行，
290	// 已发行藏品仍可转让，且封存不能撤销。
291	//
292	// 封存以一次保存完成为准：封存状态尚未原子替换原数据就发生写入错误（如
293	// 数据位置暂时无法写入）时，返回本次实际的保存错误，不返回成功，也不能用
294	// 失败后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法读取或
295	// 解析、状态未能按磁盘重建，同一个仍打开的登记册也必须保持封存前的样子：
296	// 该系列编号、创建账户、文字元数据不变且仍未封存，满足原有发行条件时仍可
297	// 发行；其已发行藏品的持有人、版本与发行、转让历史原样保留；其他系列此前
298	// 已经成功封存的封存状态不被解封。原数据仍可读取的普通保存失败同样撤销
299	// 本次变化，不依赖重新读取成功。保存条件未恢复时再次提交封存须重新尝试
300	// 保存并返回本次保存错误，不能因上次失败留下的状态直接宣告完成；随后另
301	// 一次无关操作成功保存也不会把这次未保存的封存夹带落盘。读写恢复后重新
302	// 提交封存，成功保存后才显示已封存，并按原有规则拒绝单件与整批发行。
303	func (r *Registry) SealSeries(seriesID, operator string) error {
304		r.mu.Lock()
305		defer r.mu.Unlock()
306		if err := r.checkOpen(); err != nil {
307			return err
308		}
309		s, ok := r.state.Series[seriesID]
310		if !ok {
311			return fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
312		}
313		if s.CreatorID != operator {
314			return fmt.Errorf("%w: 只有创建账户 %s 可以封存系列 %s", ErrForbidden, s.CreatorID, seriesID)
315		}
316		if s.Sealed {
317			return nil // 封存不可撤销，已成功封存的系列重复封存直接成功，不要求再次写入
318		}
319		// 保存封存前的系列记录：封存以一次保存完成为准。commit 失败且磁盘
320		// 暂时不可读、状态未能按磁盘重建时据此显式撤销，否则这次未保存的封存
321		// 会留在当前已打开的登记册中（GetSeries 显示已封存、发行被按封存拒绝、
322		// 重复封存被幂等分支直接放行），并被随后另一次成功保存夹带落盘。
323		prev := s
324		s.Sealed = true
325		r.state.Series[seriesID] = s
326		if err := r.commit(); err != nil {
327			// commit 失败时已尝试按磁盘内容重建状态：重建成功则系列已随旧状态
328			// 整体恢复未封存，写回的记录与磁盘一致；磁盘暂时不可读、状态未能
329			// 重建时本次封存仍在，显式恢复为封存前记录，藏品持有、版本与历史
330			// 本就未被触碰。返回实际写入错误，而非成功或重新读取时的错误。
331			r.state.Series[seriesID] = prev
332			return err
333		}
334		return nil
335	}
