337	// GetSeries 查询系列；不存在时返回包裹 ErrNotFound 的错误。
338	func (r *Registry) GetSeries(id string) (Series, error) {
339		r.mu.Lock()
340		defer r.mu.Unlock()
341		if err := r.checkOpen(); err != nil {
342			return Series{}, err
343		}
344		s, ok := r.state.Series[id]
345		if !ok {
346			return Series{}, fmt.Errorf("%w: 系列 %s", ErrNotFound, id)
347		}
348		return Series{ID: s.ID, CreatorID: s.CreatorID, Metadata: s.Metadata, Sealed: s.Sealed}, nil
349	}
