800	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
801	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
802	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
803	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
804	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
805	//
806	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
807	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
808	// 参数错误与引用不存在不占用请求号。
809	//
810	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
811	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
812	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
813	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
814	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
815	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
816	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
817	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
818	// 错误（首次重提不标回放），状态已满足请求则正常创建。
819	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
820		if err := req.validatePresent(); err != nil {
821			return CreateAuthorizationResult{}, err
822		}
823		r.mu.Lock()
824		defer r.mu.Unlock()
825		if err := r.checkOpen(); err != nil {
826			return CreateAuthorizationResult{}, err
827		}
828	
829		now := r.now()
830		key := requestKey(req.Operator, req.RequestID)
831		sig := createAuthzParamsSig(req)
832		if prev, ok := r.state.Requests[key]; ok {
833			return r.replayCreateAuthz(prev, sig)
834		}
835	
836		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
837			if !isValidationErr(bizErr) {
838				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
839				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
840				r.state.Requests[key] = request{
841					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
842					Params: sig, Rejected: true, Reason: errCode(bizErr),
843					AuthID: req.AuthID, ItemID: req.ItemID,
844				}
845				if err := r.commit(); err != nil {
846					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
847					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
848					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
849					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
850					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
851					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
852					// 为零、不标回放、结果中业务错误为空，error 保留实际
853					// 写入错误。
854					delete(r.state.Requests, key)
855					return CreateAuthorizationResult{}, err
856				}
857			}
858			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
859		}
860	
861		h := r.state.Holdings[req.ItemID]
862		a := authzRec{
863			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
864			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
865			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
866		}
867		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
868		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
869		// 一次成功保存都会把这份未保存的授权带进登记册。
870		prevAuthSeq := r.state.NextAuthSeq
871		prevEvents := len(r.state.AuthEvents)
872		r.state.Authzs[req.AuthID] = a
873		authSeq := prevAuthSeq + 1
874		r.state.NextAuthSeq = authSeq
875		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
876			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
877			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
878			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
879		})
880		r.state.Requests[key] = request{
881			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
882			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
883		}
884		if err := r.commit(); err != nil {
885			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
886			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
887			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
888			if _, ok := r.state.Requests[key]; ok {
889				delete(r.state.Requests, key)
890				delete(r.state.Authzs, req.AuthID)
891				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
892				r.state.NextAuthSeq = prevAuthSeq
893			}
894			return CreateAuthorizationResult{}, err
895		}
896		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
897	}
898	
899	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
900		h, ok := r.state.Holdings[req.ItemID]
901		if !ok {
902			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
903				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
904			}
905			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
906		}
907		op, ok := r.state.Accounts[req.Operator]
908		if !ok {
909			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
910		}
911		trustee, ok := r.state.Accounts[req.TrusteeID]
912		if !ok {
913			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
914		}
915		to, ok := r.state.Accounts[req.ToID]
916		if !ok {
917			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
918		}
919		if req.TrusteeID == req.Operator {
920			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
921		}
922		if req.ToID == req.Operator {
923			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
924		}
925		if !op.Active {
926			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
927		}
928		if !trustee.Active {
929			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
930		}
931		if !to.Active {
932			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
933		}
934		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
935		if _, exists := r.state.Authzs[req.AuthID]; exists {
936			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
937		}
938		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
939		if !req.ExpiresAt.After(now) {
940			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
941				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
942		}
943		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
944			req.Operator != h.OwnerID {
945			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
946				ErrConflict, req.ItemID, h.OwnerID, h.Version)
947		}
948		return nil
949	}
950	
951	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
952		if prev.Kind != "auth_create" || prev.Params != sig {
953			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
954				ErrRequestConflict, prev.Operator, prev.RequestID)
955		}
956		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
957			Status: AuthActive, Replayed: true}
958		if prev.Rejected {
959			res.Err = codeErr(prev.Reason)
960			return res, res.Err
961		}
962		return res, nil
963	}
964	
965	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
966		b, _ := json.Marshal(struct {
967			Kind   string `json:"kind"`
968			AuthID string `json:"auth_id"`
969			Reason string `json:"reason"`
970		}{"auth_revoke", req.AuthID, req.Reason})
971		return string(b)
972	}
973	
974	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销
975	// （非授权人返回 ErrForbidden）；已使用的授权不能撤销
976	// （ErrAuthorizationUsed）。授权已撤销时再次撤销不新增授权变更记录，按
977	// 成功返回。到期但未使用的授权仍可撤销（变更记录从 expired 记为
978	// revoked）。请求号语义与其他操作一致。
979	//
980	// 无权（ErrForbidden）与已使用（ErrAuthorizationUsed）两类业务拒绝同样
981	// 需要落盘：拒绝结果尚未写入原登记册而保存失败（如数据位置暂时无法写入）
982	// 时，返回实际保存错误，不能只返回上述业务错误让调用者误以为拒绝结果已经
983	// 记住；结果为空（无授权编号、无状态、业务错误为空、不标回放），error 保留
984	// 保存失败的原因。这次未保存的拒绝不改变授权内容、授权变更记录、藏品当前
985	// 持有人和版本，也不占用操作者的本次请求号——即使保存失败后原登记册数据
986	// 暂时无法读取、状态未能按磁盘重建，未保存的拒绝也不能留在当前已打开的
987	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用同一操作者、
988	// 请求号、授权编号和原因重新提交，按当时的授权情况重新处理：拒绝条件仍存在
989	// 时先成功保存此次拒绝再返回相应业务错误（首次重提不标回放），此后完全相同
990	// 的提交才回放它；失败保存的请求不适用请求号冲突规则，该操作者用同号撤销另
991	// 一份自己有权撤销的授权时不会遭遇请求号冲突。必填内容缺失及授权不存在仍
992	// 直接按原错误拒绝、不占用请求号，不因当前无法保存而变成保存错误。
993	//
994	// 撤销成功同样以保存完成为准：授权状态、撤销时间、撤销记录、授权历史序号
995	// 与请求结果都尚未写入原登记册而保存失败时，返回实际保存错误而非撤销成功，
996	// 结果为空（无授权编号、无状态、业务错误为空、不标回放）。即使失败后原数据
997	// 暂时无法读取、状态未能按磁盘重建，这份撤销也必须从当前仍打开的登记册中
998	// 整体撤销：保留撤销前的授权内容与撤销时间，不新增撤销记录，授权历史序号与
999	// 请求号都不被消耗；藏品的持有人、版本以及此前已保存的其他授权和历史原样
1000	// 保留，随后另一次正常操作成功保存也不会把这份未保存的撤销一并写入。失败后
1001	// 能否代转仍按原规则判断：持有版本未变、相关账户可用且未到期时受托人仍能
1002	// 正常使用；已到期或藏品已易手则继续返回相应业务拒绝，不能为恢复撤销前状态
1003	// 让旧授权重新可用。保存条件恢复后用同一操作者、授权编号、原因和请求号再次
1004	// 撤销，按此时的授权处理而不回放那次未保存的成功：授权仍未使用且允许撤销时
1005	// 本次才完成撤销并新增一条记录（记录本次生效的时间、操作者、原因与前后状态，
1006	// 不标回放），再原样提交才回放这一已保存结果。仅授权人能撤销、已使用授权
1007	// 拒绝撤销、已撤销授权再次撤销不新增记录的既有行为不变；这些已经保存的终态
1008	// 不被本次失败恢复。
1009	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
1010		missing := []string{}
1011		if strings.TrimSpace(req.Operator) == "" {
1012			missing = append(missing, "operator")
1013		}
1014		if strings.TrimSpace(req.Reason) == "" {
1015			missing = append(missing, "reason")
1016		}
1017		if strings.TrimSpace(req.RequestID) == "" {
1018			missing = append(missing, "request_id")
1019		}
1020		if strings.TrimSpace(req.AuthID) == "" {
1021			missing = append(missing, "auth_id")
1022		}
1023		if len(missing) > 0 {
1024			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
1025				ErrInvalidArgument, strings.Join(missing, ", "))
1026		}
1027		r.mu.Lock()
1028		defer r.mu.Unlock()
1029		if err := r.checkOpen(); err != nil {
1030			return RevokeAuthorizationResult{}, err
1031		}
1032	
1033		now := r.now()
1034		key := requestKey(req.Operator, req.RequestID)
1035		sig := revokeAuthzParamsSig(req)
1036		if prev, ok := r.state.Requests[key]; ok {
1037			return r.replayRevokeAuthz(prev, sig)
1038		}
1039	
1040		a, ok := r.state.Authzs[req.AuthID]
1041		if !ok {
1042			// 引用不存在不占用请求号。
1043			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1044			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
1045		}
1046		if a.GranterID != req.Operator {
1047			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
1048				ErrForbidden, a.GranterID, req.AuthID)
1049			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
1050				return RevokeAuthorizationResult{}, err
1051			}
1052			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1053		}
1054		switch authzCurrentStatus(a, now) {
1055		case AuthUsed:
1056			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
1057			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
1058				return RevokeAuthorizationResult{}, err
1059			}
1060			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1061		case AuthRevoked:
1062			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
1063			// 相同请求重放回放同一结果。
1064			r.state.Requests[key] = request{
1065				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1066				Params: sig, AuthID: req.AuthID,
1067			}
1068			if err := r.commit(); err != nil {
1069				// 请求结果落盘失败：这次重放登记没有被记住，与撤销成功路径一致——
1070				// 显式撤销尚未保存的请求号占用，覆盖磁盘暂时不可读、状态未能按磁盘
1071				// 重建的情形，返回空结果与实际保存错误。已撤销终态本就存在于磁盘，
1072				// 无需回滚授权本身。
1073				delete(r.state.Requests, key)
1074				return RevokeAuthorizationResult{}, err
1075			}
1076			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1077		}
1078	
1079		// 回滚基点：撤销以一次保存完成为准。记录撤销前的授权记录、授权历史
1080		// 长度与历史序号，保存失败且磁盘暂时不可读、状态未能按磁盘重建时据此
1081		// 整体撤销，否则这份未保存的撤销会留在当前已打开的登记册中（授权显示
1082		// 已撤销、受托人被拒绝代转、重复撤销被幂等分支直接放行），并随之后另
1083		// 一次成功保存夹带落盘，原请求重提也会被误当成已保存成功直接回放。
1084		prevAuthz := a
1085		prevAuthSeq := r.state.NextAuthSeq
1086		prevEvents := len(r.state.AuthEvents)
1087		from := AuthActive
1088		if authzCurrentStatus(a, now) == AuthExpired {
1089			from = AuthExpired
1090		}
1091		a.Status = "revoked"
1092		a.RevokedAt = now
1093		r.state.Authzs[req.AuthID] = a
1094		authSeq := prevAuthSeq + 1
1095		r.state.NextAuthSeq = authSeq
1096		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1097			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
1098			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1099			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
1100		})
1101		r.state.Requests[key] = request{
1102			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1103			Params: sig, AuthID: req.AuthID,
1104		}
1105		if err := r.commit(); err != nil {
1106			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随
1107			// 旧状态整体撤销（授权仍未撤销、无本次撤销记录、请求记录不存在、
1108			// 序号未消耗），写回的记录与磁盘一致，无需再动；磁盘暂时不可读、
1109			// 状态未能重建时本次改动仍在，据此把这份未保存的撤销全部撤销，让
1110			// 当前已打开的登记册回到提交前状态——授权内容与撤销时间恢复原样，
1111			// 持有版本未变且账户可用、未到期时受托人仍可正常使用该授权；也不
1112			// 被随后另一次成功保存带入。返回实际写入错误而非成功或业务拒绝，
1113			// 结果为空：无授权编号、无状态、不标回放、结果中业务错误为空。
1114			if _, pending := r.state.Requests[key]; pending {
1115				delete(r.state.Requests, key)
1116				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
1117				r.state.NextAuthSeq = prevAuthSeq
1118				r.state.Authzs[req.AuthID] = prevAuthz
1119			}
1120			return RevokeAuthorizationResult{}, err
1121		}
1122		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1123	}
