1332	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1333		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1334			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1335				ErrRequestConflict, prev.Operator, prev.RequestID)
1336		}
1337		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1338			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1339		if prev.Rejected {
1340			res.Err = codeErr(prev.Reason)
1341			return res, res.Err
1342		}
1343		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1344		// 原价款与应付明细，不重复计入。
1345		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1346		return res, nil
1347	}
1348	
1349	// ---- 授权查询 ----
1350	
1351	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1352	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1353	// 到期但尚未终结的授权返回 AuthExpired。
1354	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1355		r.mu.Lock()
1356		defer r.mu.Unlock()
1357		if err := r.checkOpen(); err != nil {
1358			return Authorization{}, err
1359		}
1360		a, ok := r.state.Authzs[authID]
1361		if !ok {
1362			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1363		}
1364		return Authorization{
1365			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1366			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1367			Status:    authzCurrentStatus(a, r.now()),
1368			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1369			RevokedAt: a.RevokedAt,
1370		}, nil
1371	}
1372	
1373	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1374	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1375	// 不存在时返回包裹 ErrNotFound 的错误。
1376	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1377		r.mu.Lock()
1378		defer r.mu.Unlock()
1379		if err := r.checkOpen(); err != nil {
1380			return nil, err
1381		}
1382		if _, ok := r.state.Items[itemID]; !ok {
1383			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1384		}
1385		out := make([]AuthorizationEvent, 0)
1386		for _, e := range r.state.AuthEvents {
1387			if e.ItemID != itemID {
1388				continue
1389			}
1390			out = append(out, AuthorizationEvent{
1391				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1392				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1393				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1394				OccurredAt: e.OccurredAt,
1395			})
1396		}
1397		return out, nil
1398	}
1399	
1400	// ---- 查询 ----
1401	
1402	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1403	func (r *Registry) GetItem(id string) (Item, error) {
1404		r.mu.Lock()
1405		defer r.mu.Unlock()
1406		if err := r.checkOpen(); err != nil {
1407			return Item{}, err
1408		}
1409		it, ok := r.state.Items[id]
1410		if !ok {
1411			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1412		}
1413		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1414			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1415	}
1416	
1417	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1418	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1419		r.mu.Lock()
1420		defer r.mu.Unlock()
1421		if err := r.checkOpen(); err != nil {
1422			return Holding{}, err
1423		}
1424		h, ok := r.state.Holdings[itemID]
1425		if !ok {
1426			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1427		}
1428		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1429	}
1430	
1431	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1432	// ErrNotFound 的错误；停用账户仍可正常查询。
1433	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1434		r.mu.Lock()
1435		defer r.mu.Unlock()
1436		if err := r.checkOpen(); err != nil {
1437			return nil, err
1438		}
1439		if _, ok := r.state.Accounts[accountID]; !ok {
1440			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1441		}
1442		out := make([]Holding, 0)
1443		for _, h := range r.state.Holdings {
1444			if h.OwnerID == accountID {
1445				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1446			}
1447		}
1448		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1449		return out, nil
1450	}
1451	
1452	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1453	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1454	// 返回包裹 ErrNotFound 的错误。
1455	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1456		r.mu.Lock()
1457		defer r.mu.Unlock()
1458		if err := r.checkOpen(); err != nil {
1459			return nil, err
1460		}
1461		if _, ok := r.state.Items[itemID]; !ok {
1462			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1463		}
1464		out := make([]HistoryEntry, 0)
1465		for _, e := range r.state.History {
1466			if e.ItemID != itemID {
1467				continue
1468			}
1469			out = append(out, HistoryEntry{
1470				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1471				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1472				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1473			})
1474		}
1475		return out, nil
1476	}
1477	
1478	// ---- 幂等辅助 ----
1479	
1480	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1481	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1482	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1483	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1484	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1485	func requestKey(operator, requestID string) string {
1486		b, _ := json.Marshal([2]string{operator, requestID})
1487		return string(b)
1488	}
1489	
1490	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1491	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1492	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1493	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1494	// 并回放。
1495	func isValidationErr(err error) bool {
1496		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1497	}
1498	
1499	var errCodes = map[error]string{
1500		ErrNotFound:             "not_found",
1501		ErrAlreadyExists:        "already_exists",
1502		ErrAccountInactive:      "account_inactive",
1503		ErrSeriesSealed:         "series_sealed",
1504		ErrConflict:             "conflict",
1505		ErrSameAccount:          "same_account",
1506		ErrForbidden:            "forbidden",
1507		ErrAuthorizationRevoked: "authorization_revoked",
1508		ErrAuthorizationExpired: "authorization_expired",
1509		ErrAuthorizationUsed:    "authorization_used",
1510		ErrRoyaltyFrozen:        "royalty_frozen",
1511		ErrSplitIntentRejected:  "split_intent_rejected",
1512		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1513		ErrSplitIntentInvalid:   "split_intent_invalid",
1514		ErrSplitIntentExpired:   "split_intent_expired",
1515		ErrSplitAnswered:        "split_answered",
1516	}
1517	
1518	var codeErrs = map[string]error{
1519		"not_found":              ErrNotFound,
1520		"already_exists":         ErrAlreadyExists,
1521		"account_inactive":       ErrAccountInactive,
1522		"series_sealed":          ErrSeriesSealed,
1523		"conflict":               ErrConflict,
1524		"same_account":           ErrSameAccount,
1525		"forbidden":              ErrForbidden,
1526		"authorization_revoked":  ErrAuthorizationRevoked,
1527		"authorization_expired":  ErrAuthorizationExpired,
1528		"authorization_used":     ErrAuthorizationUsed,
1529		"royalty_frozen":         ErrRoyaltyFrozen,
1530		"split_intent_rejected":  ErrSplitIntentRejected,
1531		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1532		"split_intent_invalid":   ErrSplitIntentInvalid,
1533		"split_intent_expired":   ErrSplitIntentExpired,
1534		"split_answered":         ErrSplitAnswered,
1535	}
1536	
1537	func errCode(err error) string {
1538		for sentinel, code := range errCodes {
1539			if errors.Is(err, sentinel) {
1540				return code
1541			}
1542		}
1543		return "rejected"
1544	}
1545	
1546	func codeErr(code string) error {
1547		if e, ok := codeErrs[code]; ok {
1548			return e
1549		}
1550		return errors.New("registry: 请求曾被拒绝")
1551	}
1552

