54	// assertTransferSuccessStillPending 在（成功转让保存失败后的）同一个已打开
55	// 登记册上核对：这笔转让如同从未发生，而失败前已有的内容、顺序与金额完整
56	// 保留。item 为本次未保存转让的藏品，rid 为其请求号，price 为其价款。
57	func assertTransferSuccessStillPending(t *testing.T, r *Registry, item, rid string) {
58		t.Helper()
59		// 藏品仍属提交前持有人 bob，版本没有增加，历史只有发行一条，且不出现
60		// 本次请求号。
61		h, err := r.GetHolding(item)
62		if err != nil {
63			t.Fatalf("GetHolding %s: %v", item, err)
64		}
65		if h.OwnerID != "bob" || h.Version != 1 {
66			t.Fatalf("保存失败后 %s 持有被改变: %+v", item, h)
67		}
68		hist, err := r.History(item)
69		if err != nil {
70			t.Fatalf("History %s: %v", item, err)
71		}
72		if len(hist) != 1 || hist[0].Kind != "issue" {
73			t.Fatalf("保存失败后 %s 历史多出本次转让: %+v", item, hist)
74		}
75		for _, e := range hist {
76			if e.RequestID == rid {
77				t.Fatalf("保存失败后 %s 历史出现请求号 %s: %+v", item, rid, e)
78			}
79		}
80	
81		// 持有列表：bob 仍持有 i1..i4，i5 属 carol，已合法易手的 i6 属 alice。
82		bobHoldings, err := r.HoldingsOf("bob")
83		if err != nil {
84			t.Fatal(err)
85		}
86		gotItems := map[string]bool{}
87		for _, hh := range bobHoldings {
88			gotItems[hh.ItemID] = true
89			if hh.Version != 1 {
90				t.Fatalf("保存失败后 bob 的 %s 版本被改变: %+v", hh.ItemID, hh)
91			}
92		}
93		// bob 应恰好持有 i1..i4：未保存转让的藏品没有离开，也没有多出别的。
94		wantBob := map[string]bool{"i1": true, "i2": true, "i3": true, "i4": true}
95		if len(bobHoldings) != len(wantBob) {
96			t.Fatalf("保存失败后 bob 持有清单数量异常: %+v", bobHoldings)
97		}
98		for id := range wantBob {
99			if !gotItems[id] {
100				t.Fatalf("保存失败后 bob 应仍持有 %s，实际 %+v", id, bobHoldings)
101			}
102		}
103	
104		// 历史序号不被消耗：下一条仍是 8（失败前最后一条为 7）；请求号空闲；
105		// 版税查询没有序号 8 的计算记录。
106		if r.state.NextSeq != 7 {
107			t.Fatalf("NextSeq = %d，未保存转让不应消耗历史序号，仍应为 7", r.state.NextSeq)
108		}
109		if _, ok := r.state.Requests[requestKey("bob", rid)]; ok {
110			t.Fatalf("未保存转让不应占用请求号 %s", rid)
111		}
112		if _, err := r.TransferRoyalty(8); !errors.Is(err, ErrNotFound) {
113			t.Fatalf("未保存转让不应留下序号 8 的版税计算记录: %v", err)
114		}
115	
116		// 收款账户不能多出本次转让的应付：只保留失败前序号 7（i6，10000 分）
117		// 的记录。
118		wantCarol := []PayableEntry{{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 1000, Amount: 1000}}
119		wantDave := []PayableEntry{{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 500, Amount: 500}}
120		if carolPay, err := r.PayablesOf("carol"); err != nil || !reflect.DeepEqual(carolPay, wantCarol) {
121			t.Fatalf("carol 应付 = %+v, err %v, want %+v", carolPay, err, wantCarol)
122		}
123		if davePay, err := r.PayablesOf("dave"); err != nil || !reflect.DeepEqual(davePay, wantDave) {
124			t.Fatalf("dave 应付 = %+v, err %v, want %+v", davePay, err, wantDave)
125		}
126	
127		// 失败前那笔成功转让与其他藏品原样保留。
128		tr, err := r.TransferRoyalty(7)
129		if err != nil {
130			t.Fatalf("TransferRoyalty 7: %v", err)
131		}
132		if tr.ItemID != "i6" || tr.Price != 10000 || tr.Remainder != 8500 || tr.OwnerID != "bob" ||
133			len(tr.Payables) != 2 {
134			t.Fatalf("旧转让版税记录被破坏: %+v", tr)
135		}
136		i6, _ := r.GetHolding("i6")
137		if i6.OwnerID != "alice" || i6.Version != 2 {
138			t.Fatalf("清单外 i6 受影响: %+v", i6)
139		}
140		if hist6, _ := r.History("i6"); len(hist6) != 2 || hist6[1].Seq != 7 || hist6[1].ToID != "alice" {
141			t.Fatalf("清单外 i6 历史受影响: %+v", hist6)
142		}
143		i5, _ := r.GetHolding("i5")
144		if i5.OwnerID != "carol" || i5.Version != 1 {
145			t.Fatalf("清单外 i5 受影响: %+v", i5)
146		}
147	}
